/// <summary>
/// Extension class for the Remove button on the Unit of Measure Conversion form to handle intraclass conversions
/// </summary>
[ExtensionOf(formControlStr(UnitOfMeasureConversion, AVARUMRemoveOrderIntraclass))]
internal final class AVARUMUnitOfMeasureConversion_AVARUMRemoveOrderIntraclassCtrl_Extension
{
}

Method.Source:
/// <summary>
/// Handles the clicked event of the Remove button.
/// </summary>
public void clicked()
{
    FormButtonControl buttonControl;
    FormRun formRun;
    FormDataSource formDataSource;
    UnitOfMeasureConversion unitOfMeasureConversion;

    next clicked();

    buttonControl = any2Object(this) as FormButtonControl;
    formRun = buttonControl.formRun();
    formDataSource = formRun.dataSource(formDataSourceStr(UnitOfMeasureConversion, UnitOfMeasureConversionIntraclass));
    unitOfMeasureConversion = formDataSource.cursor();
    unitOfMeasureConversion.removeOrder_AVA();

    Global::researchAllFormDataSources_AVA(formRun);
}
